    #[salsa::tracked(returns(clone))]
    fn classify_screen_sessions(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        if config.screen_session_construction_strategy(db)
            != ScreenSessionConstructionStrategyId::default()
        {
            db.record_query_body("classify_screen_sessions");
            let construction = construct_screen_intervals(db, raw, early, config, support)?;
            let construction_payload = construction.value.lease()?;
            if !construction_payload.executable() {
                let reason = construction_payload
                    .applicability
                    .refusal_reason
                    .map(b05::B05RefusalReason::canonical_id)
                    .unwrap_or("undetermined");
                return Err(format!(
                    "scientific_preflight_refused:b05={reason}:schoedel=none"
                ));
            }
            let decoded = decode_source_records(db, raw)?;
            let decoded_payload = decoded.value.lease()?;
            let rows = super::apply_screen_session_policies(
                materialize_b05_screen_rows(
                    db.stage_functions(),
                    &construction_payload,
                    &decoded_payload,
                    &early.timezone(db),
                )?,
                config.screen_session_classification_policy(db),
                config.screen_session_maximum_duration_minutes(db),
                config.screen_session_maximum_duration_disposition(db),
                config.locked_screen_audio_disposition(db),
            );
            let construction_fingerprint = super::value_fingerprint(&*construction_payload)
                .map_err(|error| format!("serialize B05 screen checkpoint: {error}"))?;
            let checkpoint = workflow_checkpoint(
                "classify_screen_sessions",
                &[("rows", &rows)],
                &[("b05Construction", &construction_fingerprint)],
            );
            return Ok(QueryValue {
                value: query_payload(db.payload_store(), Arc::new(rows)),
                checkpoint: checkpoint.clone(),
                query_group_checkpoint: Some(checkpoint_for_exact_state(
                    "device_state_timeline",
                    &checkpoint,
                )),
            });
        }
        if !raw.reconstruction_base_bytes(db).is_empty() {
            if let Some(cached) = matching_reconstruction_base(db, raw, early, config, support)? {
                if let Some(screen) = cached.value.screen.as_ref() {
                    let expected_screen_key =
                        screen_base_input_key(db, raw, early, config, support)?;
                    if screen.input_key == expected_screen_key {
                        db.record_internal_query_body("restore_reconstruction_screen");
                        return Ok(QueryValue {
                            value: query_payload(db.payload_store(), Arc::clone(&screen.rows)),
                            checkpoint: screen.classify_screen_sessions.clone(),
                            query_group_checkpoint: Some(screen.device_state_timeline.clone()),
                        });
                    }
                }
            }
        }
        if !raw.review_base_bytes(db).is_empty() {
            if let Some(cached) = matching_review_base(db, raw, early, support)? {
                if let Some(screen) = cached.value.screen.as_ref() {
                    let expected_screen_key =
                        screen_base_input_key(db, raw, early, config, support)?;
                    if screen.input_key == expected_screen_key {
                        db.record_internal_query_body("restore_review_screen");
                        return Ok(QueryValue {
                            value: query_payload(db.payload_store(), Arc::clone(&screen.rows)),
                            checkpoint: screen.classify_screen_sessions.clone(),
                            query_group_checkpoint: Some(screen.device_state_timeline.clone()),
                        });
                    }
                }
            }
        }
        db.record_query_body("classify_screen_sessions");
        let rows = derive_time_gap_evidence(db, raw, early)?;
        let rows_payload = rows.value.lease()?;
        let closes = infer_screen_session_skeletons(db, raw, early, config, support)?;
        let closes_payload = closes.value.lease()?;
        if closes_payload.is_empty() {
            return Ok(with_logical_rows(
                rows_step(db.payload_store(), "classify_screen_sessions", Vec::new()),
                "device_state_timeline",
            ));
        }
        let keyguard = index_keyguard_events(db, raw, early, config, support)?;
        let keyguard_payload = keyguard.value.lease()?;
        let forcing = parsed_apps_forcing_screen_open(db, support);
        let classified = (db.stage_functions().classify_screen_sessions)(
            &rows_payload,
            &closes_payload,
            &keyguard_payload,
            &forcing,
            ScreenClassificationSettings {
                auto_lock_timeout_seconds: support.screen_auto_lock_timeout_seconds(db),
                auto_lock_tolerance_seconds: support.screen_auto_lock_tolerance_seconds(db),
                manual_lock_max_tail_seconds: support.screen_manual_lock_max_tail_seconds(db),
                keyguard_near_stop_seconds: support.screen_keyguard_near_stop_seconds(db),
                locked_screen_audio_disposition: config.locked_screen_audio_disposition(db),
            },
        );
        Ok(with_logical_rows(
            rows_step(db.payload_store(),
                "classify_screen_sessions",
                super::apply_screen_session_policies(
                    classified,
                    config.screen_session_classification_policy(db),
                    config.screen_session_maximum_duration_minutes(db),
                    config.screen_session_maximum_duration_disposition(db),
                    config.locked_screen_audio_disposition(db),
                ),
            ),
            "device_state_timeline",
        ))
    }

