    #[derive(Clone, serde::Serialize, serde::Deserialize)]
    struct CreditSessionPlan {
        decisions: Vec<CreditDecision>,
        tolerance_minutes: f64,
    }

    #[salsa::tracked(returns(clone))]
    fn derive_credited_intervals(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<CreditSessionPlan>, String> {
        db.record_query_body("derive_credited_intervals");
        let partition = identify_credit_eligible_sessions(db, raw, early, config, support)?;
        let partition_payload = partition.value.lease()?;
        let substrate = build_activity_witness_indexes(db, raw, early, config, support)?;
        let substrate_payload = substrate.value.lease()?;
        let day_apps = summarize_daily_apps(db, raw, early, config, support)?;
        let day_apps_payload = day_apps.value.lease()?;
        let tolerance_minutes = late.device_liveness_gap_tolerance_minutes(db);
        let decisions = super::derive_credited_intervals(
            &partition_payload,
            &substrate_payload,
            &day_apps_payload,
            late.credited_session_cap_minutes(db),
            tolerance_minutes,
            late.auto_lock_bridge_seconds(db),
            late.no_witness_min_day_apps(db),
            late.screen_gating_rule(db),
        );
        let payload = checkpoint::credit_decisions_checkpoint_payload(&decisions, tolerance_minutes);
        value_payload_step(db.payload_store(),
            "derive_credited_intervals",
            CreditSessionPlan {
                decisions,
                tolerance_minutes,
            },
            &payload,
        )
    }

    #[derive(Clone, serde::Serialize, serde::Deserialize)]
    pub(crate) struct CreditEmissionStep {
        pub(crate) emission: CreditEmission,
    }

    #[salsa::tracked(returns(clone))]
    fn materialize_credited_rows(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<CreditEmissionStep>, String> {
        db.record_query_body("materialize_credited_rows");
        let plan = derive_credited_intervals(db, raw, early, config, support, late)?;
        let plan_payload = plan.value.lease()?;
        let partition = identify_credit_eligible_sessions(db, raw, early, config, support)?;
        let partition_payload = partition.value.lease()?;
        let substrate = build_activity_witness_indexes(db, raw, early, config, support)?;
        let substrate_payload = substrate.value.lease()?;
        let emission = super::materialize_credited_rows(
            &partition_payload,
            &plan_payload.decisions,
            &substrate_payload,
            plan_payload.tolerance_minutes,
        );
        let payload = emission.checkpoint_payload();
        value_payload_step(db.payload_store(),
            "materialize_credited_rows",
            CreditEmissionStep { emission },
            &payload,
        )
    }

    #[salsa::tracked(returns(clone))]
    fn assemble_credit_outputs(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<CreditResult>, String> {
        db.record_query_body("assemble_credit_outputs");
        let partition = identify_credit_eligible_sessions(db, raw, early, config, support)?;
        let partition_payload = partition.value.lease()?;
        let screen_incapable = assess_screen_evidence_capability(db, raw, early, config, support)?;
        let screen_incapable_payload = screen_incapable.value.lease()?;
        let emission = materialize_credited_rows(db, raw, early, config, support, late)?;
        let emission_payload = emission.value.lease()?;
        let result = super::assemble_credit_outputs(
            &partition_payload,
            &screen_incapable_payload,
            &emission_payload.emission,
        );
        let payload = result.checkpoint_payload();
        value_payload_step(db.payload_store(), "assemble_credit_outputs", result, &payload)
    }

    // ---- B08 notification-derived proxy contacts ------------------------
    //
    // These read `mark_app_policy_matches`, not the episode rows: a
    // notification never becomes an episode, so the policy row is the only
    // place it exists. The policy stage precedes the event-retention set and
    // no retention set keeps a notification type, so the contact channel is
    // outside the retention axis: it reports every notification row.

    #[salsa::tracked(returns(clone))]
    fn select_notification_events(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        let _timer = QueryTimer::start("select_notification_events");
        db.record_query_body("select_notification_events");
        let rule = late.notification_proxy_rule(db);
        let policy_rows = analysis_policy_rows(db, raw, early, config, support)?;
        let policy_rows_payload = policy_rows.value.lease()?;
        let contacts = super::select_notification_events(&policy_rows_payload, rule);
        let payload = notification::notification_selection_checkpoint(&contacts, rule);
        let checkpoint =
            rows_and_value_checkpoint("select_notification_events", &contacts, &payload)?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(contacts)),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    #[salsa::tracked(returns(clone))]
    fn index_observed_usage_spans(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<ObservedUsageSpans>, String> {
        let _timer = QueryTimer::start("index_observed_usage_spans");
        db.record_query_body("index_observed_usage_spans");
        // The index exists only to answer "was this notification inside time
        // an app-usage session already accounts for", so it is empty with no
        // rule selected. Reading the rule here is what makes that dependency
        // declarable: without it the runtime's own binding guard reported
        // "tracked query output changed without a changed bound input" on the
        // none -> rule transition, because the index went from never computed
        // to computed with nothing bound explaining why.
        let rule = late.notification_proxy_rule(db);
        let spans = if matches!(rule, NotificationProxyRule::None) {
            ObservedUsageSpans::default()
        } else {
            let rows = assign_usage_session_ids(db, raw, early, config, support)?;
            let rows_payload = rows.value.lease()?;
            super::index_observed_usage_spans(&rows_payload)
        };
        // Fingerprint the value itself, not a `serde_json::Value` of it: the
        // round trip through `Value` reorders struct fields alphabetically and
        // would disagree with the sequential oracle.
        let checkpoint = value_payload_checkpoint("index_observed_usage_spans", &spans)?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(spans)),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    #[salsa::tracked(returns(clone))]
    fn classify_notification_contacts(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        let _timer = QueryTimer::start("classify_notification_contacts");
        db.record_query_body("classify_notification_contacts");
        let rule = late.notification_proxy_rule(db);
        let selected = select_notification_events(db, raw, early, config, support, late)?;
        let selected_payload = selected.value.lease()?;
        let spans = index_observed_usage_spans(db, raw, early, config, support, late)?;
        let spans_payload = spans.value.lease()?;
        let mut contacts = (*selected_payload).clone();
        let counts = super::classify_notification_contacts(&mut contacts, &spans_payload, rule);
        let checkpoint =
            rows_and_value_checkpoint("classify_notification_contacts", &contacts, &counts)?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(contacts)),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    #[salsa::tracked(returns(clone))]
    fn assemble_notification_contact_outputs(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        let _timer = QueryTimer::start("assemble_notification_contact_outputs");
        db.record_query_body("assemble_notification_contact_outputs");
        // Self-gating, not belt-and-braces: this is the only step that reads
        // the app codebook artifact for the proxy channel, so the rule has to
        // be read here for the codebook binding to carry the same condition.
        // With no rule selected the channel emits nothing and the artifact is
        // never touched.
        let rule = late.notification_proxy_rule(db);
        let classified = if matches!(rule, NotificationProxyRule::None) {
            Arc::new(Vec::new())
        } else {
            classify_notification_contacts(db, raw, early, config, support, late)?
                .value
                .lease()?
                .shared()
        };
        let enabled = !matches!(rule, NotificationProxyRule::None) && support.use_app_codebook(db);
        let codebook = if enabled {
            parsed_codebook(db, support)
        } else {
            Arc::default()
        };
        let mut contacts = (*classified).clone();
        // The same enrichment every app row receives, from the same owner. A
        // proxy channel with blank category columns would be a second, poorer
        // join.
        annotations::enrich_codebook_rows(&mut contacts, enabled, &codebook);
        let payload = annotations::codebook_checkpoint_payload(codebook.is_empty());
        let checkpoint = rows_and_value_checkpoint(
            "assemble_notification_contact_outputs",
            &contacts,
            &payload,
        )?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(contacts)),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    // ---- B09 polled-method emulation ------------------------------------
    //
    // These read the cleaned, session-numbered episode rows, because only an
    // episode says which package was foreground at an instant. Each self-gates
    // on the method: with no method selected the channel emits nothing and
    // none of these touches the episode rows at all, which is what lets the
    // group be declared inapplicable rather than merely idle.

    #[salsa::tracked(returns(clone))]
    fn sample_polled_timeline(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<Vec<PolledSample>>, String> {
        let _timer = QueryTimer::start("sample_polled_timeline");
        db.record_query_body("sample_polled_timeline");
        let method = late.polled_emulation_method(db);
        let interval_ns = super::seconds_to_ns_floor(late.polled_emulation_interval_seconds(db));
        let samples = if method.emits_emulation() {
            let rows = assign_usage_session_ids(db, raw, early, config, support)?;
            let rows_payload = rows.value.lease()?;
            super::sample_polled_timeline(&rows_payload, interval_ns)
        } else {
            Vec::new()
        };
        let checkpoint = value_payload_checkpoint(
            "sample_polled_timeline",
            &polled::polled_sample_checkpoint(interval_ns, samples.len()),
        )?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(samples)),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    #[salsa::tracked(returns(clone))]
    fn group_polled_runs(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<Vec<PolledRun>>, String> {
        let _timer = QueryTimer::start("group_polled_runs");
        db.record_query_body("group_polled_runs");
        let method = late.polled_emulation_method(db);
        let interval_ns = super::seconds_to_ns_floor(late.polled_emulation_interval_seconds(db));
        let gap_ns = super::seconds_to_ns_floor(late.polled_emulation_gap_seconds(db));
        let (runs, counts) = if method.emits_emulation() {
            let rows = assign_usage_session_ids(db, raw, early, config, support)?;
            let rows_payload = rows.value.lease()?;
            let samples = sample_polled_timeline(db, raw, early, config, support, late)?;
            let samples = &*samples.value.lease()?;
            let runs =
                super::group_polled_runs(&rows_payload, samples, method, interval_ns, gap_ns);
            let counts = polled::polled_counts(method, interval_ns, gap_ns, samples.len(), &runs);
            (runs, counts)
        } else {
            (
                Vec::new(),
                polled::polled_counts(method, interval_ns, gap_ns, 0, &[]),
            )
        };
        let checkpoint = value_payload_checkpoint("group_polled_runs", &counts)?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(runs)),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    #[salsa::tracked(returns(clone))]
    fn materialize_polled_rows(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        let _timer = QueryTimer::start("materialize_polled_rows");
        db.record_query_body("materialize_polled_rows");
        let method = late.polled_emulation_method(db);
        let interval_ns = super::seconds_to_ns_floor(late.polled_emulation_interval_seconds(db));
        let gap_ns = super::seconds_to_ns_floor(late.polled_emulation_gap_seconds(db));
        let (emulated, counts) = if method.emits_emulation() {
            let rows = assign_usage_session_ids(db, raw, early, config, support)?;
            let rows_payload = rows.value.lease()?;
            let records = group_polled_runs(db, raw, early, config, support, late)?;
            let records_payload = records.value.lease()?;
            let runs = &*records_payload;
            let counts = polled::polled_counts(method, interval_ns, gap_ns, runs.iter().map(|run| run.sample_count).sum(), runs);
            (
                super::materialize_polled_rows(&rows_payload, runs, method, interval_ns),
                counts,
            )
        } else {
            (
                Vec::new(),
                polled::polled_counts(method, interval_ns, gap_ns, 0, &[]),
            )
        };
        let checkpoint = rows_and_value_checkpoint("materialize_polled_rows", &emulated, &counts)?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(emulated)),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    #[salsa::tracked(returns(clone))]
    fn assemble_polled_emulation_outputs(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        let _timer = QueryTimer::start("assemble_polled_emulation_outputs");
        db.record_query_body("assemble_polled_emulation_outputs");
        // Self-gating for the same reason B08's assembly is: this is the only
        // step that reads the app codebook artifact for the emulation channel,
        // so the method has to be read here for the codebook binding to carry
        // the same condition.
        let method = late.polled_emulation_method(db);
        let materialized = if method.emits_emulation() {
            materialize_polled_rows(db, raw, early, config, support, late)?
                .value
                .lease()?
                .shared()
        } else {
            Arc::new(Vec::new())
        };
        let enabled = method.emits_emulation() && support.use_app_codebook(db);
        let codebook = if enabled {
            parsed_codebook(db, support)
        } else {
            Arc::default()
        };
        let mut emulated = (*materialized).clone();
        annotations::enrich_codebook_rows(&mut emulated, enabled, &codebook);
        let payload = annotations::codebook_checkpoint_payload(codebook.is_empty());
        let checkpoint = rows_and_value_checkpoint(
            "assemble_polled_emulation_outputs",
            &emulated,
            &payload,
        )?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(emulated)),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    fn study_window_source_rows(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        if config.usage_session_mode(db) == UsageSessionMode::ScreenUsage {
            classify_screen_sessions(db, raw, early, config, support)
        } else {
            assign_usage_session_ids(db, raw, early, config, support)
        }
    }

    #[salsa::tracked(returns(clone))]
    fn resolve_participant_windows(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late_support: LateSupportInput,
    ) -> Result<QueryValue<Vec<ResolvedParticipantWindow>>, String> {
        let _timer = QueryTimer::start("resolve_participant_windows");
        db.record_query_body("resolve_participant_windows");
        let rows = study_window_source_rows(db, raw, early, config, support)?;
        let rows_payload = rows.value.lease()?;
        let windows = parsed_study_windows(db, late_support)?;
        let screen_rows = (config.usage_session_mode(db) == UsageSessionMode::AppAndScreenUsage)
            .then(|| classify_screen_sessions(db, raw, early, config, support))
            .transpose()?;
        let cache_key = format!(
            "{}|{}|{:?}",
            rows.checkpoint.terminal_digest,
            screen_rows
                .as_ref()
                .map(|step| step.checkpoint.terminal_digest.as_str())
                .unwrap_or("none"),
            windows,
        );
        let cached = db
            .alternation_caches()
            .try_lock()
            .expect("alternation caches re-entered: a lock guard escaped across a nested query")
            .participant_windows
            .lookup(&cache_key)?;
        if let Some(cached) = cached {
            #[cfg(feature = "query-timing")]
            eprintln!("alternation_cache hit=resolve_participant_windows");
            return Ok(cached);
        }
        let mut resolved = super::resolve_windows(&rows_payload, &windows);
        if let Some(screen_rows) = screen_rows {
            let screen_payload = screen_rows.value.lease()?;
            for entry in super::resolve_windows(&screen_payload, &windows) {
                if !resolved.iter().any(|known| known.participant_id == entry.participant_id) {
                    resolved.push(entry);
                }
            }
        }
        let result = value_step(db.payload_store(), "resolve_participant_windows", resolved)?;
        db.alternation_caches()
            .try_lock()
            .expect("alternation caches re-entered: a lock guard escaped across a nested query")
            .participant_windows
            .store(db.payload_store(), cache_key, result.clone());
        Ok(result)
    }

    #[salsa::tracked(returns(clone))]
    fn apply_participant_windows(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
        late_support: LateSupportInput,
    ) -> Result<QueryValue<WindowedRows>, String> {
        let _timer = QueryTimer::start("apply_participant_windows");
        db.record_query_body("apply_participant_windows");
        let rows = study_window_source_rows(db, raw, early, config, support)?;
        let rows_payload = rows.value.lease()?;
        let resolved = resolve_participant_windows(db, raw, early, config, support, late_support)?;
        let resolved_payload = resolved.value.lease()?;
        let enabled = late.enable_study_window_filter(db);
        let windows = parsed_study_windows(db, late_support)?;
        if enabled && windows.is_empty() {
            return Err(
                "Study dates file is required when study-window filtering is enabled".into(),
            );
        }
        if config.review_only(db) && !enabled {
            let participants_without_window = attribution::disabled_window_participants(&resolved_payload);
            let payload = attribution::window_metadata(false, 0, &participants_without_window);
            let checkpoint = review_passthrough_checkpoint(
                "apply_participant_windows",
                &rows.checkpoint,
                &payload,
            )?;
            let query_group_checkpoint = workflow_checkpoint(
                "observation_window",
                &[],
                &[("review_passthrough", checkpoint.terminal_digest.as_bytes())],
            );
            return Ok(QueryValue {
                value: query_payload(db.payload_store(), Arc::new(WindowedRows {
                    rows: rows.value.clone(),
                    dropped_rows: 0,
                    participants_without_window,
                    applied: false,
                })),
                checkpoint,
                query_group_checkpoint: Some(query_group_checkpoint),
            });
        }
        let value = super::super::payload::filter_to_window(db.payload_store(), &rows.value, &resolved_payload, enabled, &windows)?;
        let exact_same_rows = value.rows.same_payload(&rows.value);
        let value_rows = value.rows.lease()?;
        let payload = attribution::window_metadata(value.applied, value.dropped_rows, &value.participants_without_window);
        let checkpoint = if exact_same_rows {
            let fingerprint = super::value_fingerprint(&payload).map_err(|error| {
                format!("serialize apply_participant_windows checkpoint: {error}")
            })?;
            checkpoint_for_exact_row_state(
                "apply_participant_windows",
                &rows.checkpoint,
                &[("value", &fingerprint)],
            )
        } else {
            rows_and_value_checkpoint_reusing(
                "apply_participant_windows",
                &value_rows,
                &rows_payload,
                &rows.checkpoint,
                &payload,
            )?
        };
        let query_group_checkpoint = if exact_same_rows {
            checkpoint_for_exact_row_state("observation_window", &checkpoint, &[])
        } else {
            workflow_rows_checkpoint("observation_window", &value_rows)
        };
        drop(value_rows);
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(value)),
            checkpoint,
            query_group_checkpoint: Some(query_group_checkpoint),
        })
    }

    #[salsa::tracked(returns(clone))]
    fn resolve_sharing_status(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
        late_support: LateSupportInput,
    ) -> Result<QueryValue<SharingResolutionValue>, String> {
        let _timer = QueryTimer::start("resolve_sharing_status");
        db.record_query_body("resolve_sharing_status");
        let windowed =
            apply_participant_windows(db, raw, early, config, support, late, late_support)?;
        let windowed_payload = windowed.value.lease()?;
        let enabled = late.enable_person_attribution(db);
        let sharing = if enabled {
            parsed_device_sharing(db, late_support)?
        } else {
            Arc::default()
        };
        let value = super::resolve_sharing(&windowed_payload.rows.lease()?, enabled, &sharing)?;
        match &value {
            SharingResolutionValue::Disabled => value_payload_step(db.payload_store(),
                "resolve_sharing_status",
                value,
                &serde_json::json!({"enabled": false}),
            ),
            SharingResolutionValue::Enabled(resolution) => {
                let checkpoint = value_payload_checkpoint("resolve_sharing_status", resolution)?;
                Ok(QueryValue {
                    value: query_payload(db.payload_store(), Arc::new(value)),
                    checkpoint,
                    query_group_checkpoint: None,
                })
            }
        }
    }

