    #[salsa::tracked(returns(clone))]
    fn classify_person_attribution(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
        late_support: LateSupportInput,
    ) -> Result<QueryValue<AttributedRows>, String> {
        let _timer = QueryTimer::start("classify_person_attribution");
        db.record_query_body("classify_person_attribution");
        let windowed =
            apply_participant_windows(db, raw, early, config, support, late, late_support)?;
        let windowed_payload = windowed.value.lease()?;
        if config.review_only(db) && !late.enable_person_attribution(db) {
            let payload = attribution::attribution_checkpoint_payload(None);
            let checkpoint = review_passthrough_checkpoint(
                "classify_person_attribution",
                &windowed.checkpoint,
                &payload,
            )?;
            let query_group_checkpoint = workflow_checkpoint(
                "attribute_person",
                &[],
                &[("review_passthrough", checkpoint.terminal_digest.as_bytes())],
            );
            return Ok(QueryValue {
                value: query_payload(db.payload_store(), Arc::new(AttributedRows {
                    rows: windowed_payload.rows.clone(),
                    report: None,
                    shared_participants: BTreeSet::new(),
                })),
                checkpoint,
                query_group_checkpoint: Some(query_group_checkpoint),
            });
        }
        let sharing = resolve_sharing_status(db, raw, early, config, support, late, late_support)?;
        let sharing_payload = sharing.value.lease()?;
        let survey = index_survey_responses(db, late, late_support)?;
        let survey_payload = survey.value.lease()?;
        let value = super::super::payload::classify_person_attribution(db.payload_store(),
            &windowed_payload.rows,
            &sharing_payload,
            &survey_payload,
        )?;
        let exact_same_rows = value.rows.same_payload(&windowed_payload.rows);
        let value_rows = value.rows.lease()?;
        let payload = attribution::attribution_checkpoint_payload(value.report.as_ref());
        let checkpoint = if exact_same_rows {
            let fingerprint = super::value_fingerprint(&payload).map_err(|error| {
                format!("serialize classify_person_attribution checkpoint: {error}")
            })?;
            checkpoint_for_exact_row_state(
                "classify_person_attribution",
                &windowed.checkpoint,
                &[("value", &fingerprint)],
            )
        } else {
            rows_and_value_checkpoint_reusing(
                "classify_person_attribution",
                &value_rows,
                &windowed_payload.rows.lease()?,
                &windowed.checkpoint,
                &payload,
            )?
        };
        let shared_fingerprint = super::value_fingerprint(&value.shared_participants)
            .map_err(|error| format!("serialize shared-participant checkpoint: {error}"))?;
        let query_group_checkpoint = if exact_same_rows {
            checkpoint_for_exact_row_state(
                "attribute_person",
                &checkpoint,
                &[("shared_participants", &shared_fingerprint)],
            )
        } else {
            workflow_checkpoint(
                "attribute_person",
                &[("rows", &value_rows[..])],
                &[("shared_participants", &shared_fingerprint)],
            )
        };
        drop(value_rows);
        Ok(QueryValue {
            value: query_payload(db.payload_store(), Arc::new(value)),
            checkpoint,
            query_group_checkpoint: Some(query_group_checkpoint),
        })
    }

    /// Divide a session that spans local midnight so each calendar day
    /// receives the share of the session that actually fell inside it. The
    /// boundary itself never moves: it stays at local midnight in the run's
    /// timezone. Under the default rule the session keeps its whole duration
    /// on the day it started and this query is an exact passthrough.
    #[salsa::tracked(returns(clone))]
    fn divide_sessions_at_day_boundary(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
        late_support: LateSupportInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        let _timer = QueryTimer::start("divide_sessions_at_day_boundary");
        db.record_query_body("divide_sessions_at_day_boundary");
        let attributed =
            classify_person_attribution(db, raw, early, config, support, late, late_support)?;
        let attributed_payload = attributed.value.lease()?;
        let rule = late.day_boundary_attribution(db);
        let applied = rule.divides_sessions();
        if config.review_only(db) && !applied {
            let checkpoint = review_passthrough_checkpoint(
                "divide_sessions_at_day_boundary",
                &attributed.checkpoint,
                &serde_json::json!({"applied": false}),
            )?;
            return Ok(QueryValue {
                value: attributed_payload.rows.clone(),
                checkpoint,
                query_group_checkpoint: None,
            });
        }
        if !applied {
            let fingerprint = super::value_fingerprint(&serde_json::json!({"applied": false}))
                .map_err(|error| {
                    format!("serialize divide_sessions_at_day_boundary checkpoint: {error}")
                })?;
            return Ok(QueryValue {
                value: attributed_payload.rows.clone(),
                checkpoint: checkpoint_for_exact_row_state(
                    "divide_sessions_at_day_boundary",
                    &attributed.checkpoint,
                    &[("value", &fingerprint)],
                ),
                query_group_checkpoint: None,
            });
        }
        let rows = Arc::new(super::split_sessions_at_local_midnight(
            (*attributed_payload.rows.lease()?).clone(),
            rule,
        ));
        let checkpoint = rows_and_value_checkpoint(
            "divide_sessions_at_day_boundary",
            &rows,
            &serde_json::json!({"applied": true}),
        )?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), rows),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

    #[salsa::tracked(returns(clone))]
    fn synthesize_placeholder_rows(
        db: &dyn EarlyStepDb,
        raw: EarlyRawInput,
        early: EarlyConfigInput,
        config: UsageConfigInput,
        support: UsageSupportInput,
        late: LateConfigInput,
        late_support: LateSupportInput,
    ) -> Result<QueryValue<Vec<Row>>, String> {
        let _timer = QueryTimer::start("synthesize_placeholder_rows");
        db.record_query_body("synthesize_placeholder_rows");
        let attributed =
            divide_sessions_at_day_boundary(db, raw, early, config, support, late, late_support)?;
        let attributed_payload = attributed.value.lease()?;
        let applied = late.add_no_activity_placeholder_days(db);
        if config.review_only(db) && !applied {
            let checkpoint = review_passthrough_checkpoint(
                "synthesize_placeholder_rows",
                &attributed.checkpoint,
                &serde_json::json!({"applied": false}),
            )?;
            return Ok(QueryValue {
                value: attributed.value.clone(),
                checkpoint,
                query_group_checkpoint: None,
            });
        }
        if !applied {
            let fingerprint = super::value_fingerprint(&serde_json::json!({"applied": false}))
                .map_err(|error| {
                    format!("serialize synthesize_placeholder_rows checkpoint: {error}")
                })?;
            return Ok(QueryValue {
                value: attributed.value.clone(),
                checkpoint: checkpoint_for_exact_row_state(
                    "synthesize_placeholder_rows",
                    &attributed.checkpoint,
                    &[("value", &fingerprint)],
                ),
                query_group_checkpoint: None,
            });
        }
        let policy_rows = analysis_policy_rows(db, raw, early, config, support)?;
        let policy_rows_payload = policy_rows.value.lease()?;
        // Read only under the filter: with it off every raw day is a candidate.
        let windows = if late.enable_study_window_filter(db) {
            Some(resolve_participant_windows(db, raw, early, config, support, late_support)?)
        } else {
            None
        };
        let windows_payload = windows.as_ref().map(|resolved| resolved.value.lease()).transpose()?;
        let rows = super::synthesize_placeholder_rows(
            attributed_payload.shared(),
            &policy_rows_payload,
            applied,
            windows_payload.as_ref().map(|resolved| resolved.as_slice()),
        );
        let checkpoint = rows_and_value_checkpoint(
            "synthesize_placeholder_rows",
            &rows,
            &serde_json::json!({"applied": applied}),
        )?;
        Ok(QueryValue {
            value: query_payload(db.payload_store(), rows),
            checkpoint,
            query_group_checkpoint: None,
        })
    }

