        #[test]
        fn a_warm_base_export_after_an_option_change_matches_a_cold_one() {
            let support = PipelineV2SupportFiles::default;
            let mut options = pipeline_options();
            options.include_app_output = true;
            let mut warm = TrackedEngine::default();
            warm.execute(&csv(), &options, support(), true).unwrap();
            warm.export_review_base().unwrap();
            warm.export_reconstruction_base().unwrap();
            let changes: [fn(&mut PipelineV2Options); 3] = [
                |o| o.deduplicate_exact_rows = !o.deduplicate_exact_rows,
                |o| o.model_concurrent_usage = !o.model_concurrent_usage,
                |o| o.minimum_usage_duration = 2.0,
            ];
            let mut reencoded = BTreeSet::new();
            for change in changes {
                change(&mut options);
                warm.execute(&csv(), &options, support(), true).unwrap();
                // Call the encoders outside the export window to see which ones
                // the change invalidated; a memo hit records nothing.
                let inputs = warm.inputs.expect("completed execution");
                warm.db.take_internal_query_bodies();
                encoded_review_base(&warm.db, inputs.raw, inputs.early, inputs.usage, inputs.usage_support)
                    .unwrap();
                encoded_reconstruction_base(
                    &warm.db, inputs.raw, inputs.early, inputs.usage, inputs.usage_support,
                )
                .unwrap();
                reencoded.extend(warm.db.take_internal_query_bodies().into_iter()
                    .filter(|name| name.starts_with("encoded_")));
                warm.db.take_query_bodies();
                warm.db.take_will_execute();

                let mut cold = TrackedEngine::default();
                cold.execute(&csv(), &options, support(), true).unwrap();
                assert_eq!(warm.export_review_base().unwrap(), cold.export_review_base().unwrap());
                assert_eq!(
                    warm.export_reconstruction_base().unwrap(),
                    cold.export_reconstruction_base().unwrap(),
                );
            }
            assert_eq!(
                reencoded,
                BTreeSet::from(["encoded_reconstruction_base", "encoded_review_base"]),
                "the changes must exercise both memoized encoders",
            );
        }

        #[test]
        fn review_base_skips_early_rows_without_changing_results() {
            let baseline = pipeline_options();
            let support = PipelineV2SupportFiles::default();
            let mut producer = TrackedEngine::default();
            producer.execute(&csv(), &baseline, support, true).unwrap();
            let review_base = producer.export_review_base().unwrap().expect("base within its ceiling");
            let decoded = decode_review_base_bytes(&review_base).unwrap();
            assert_registered_query_ids(
                "review base",
                decoded.metadata.query_checkpoints.keys(),
                &[
                    "validate_remap_rules",
                    "decode_source_records",
                    "remove_missing_timestamps",
                    "attach_device_models",
                    "canonicalize_source_rows",
                    "order_source_records",
                    "collect_timezone_observations",
                    "estimate_dominant_timezone",
                    "resolve_timezone_strategy",
                    "standardize_event_clock",
                    "summarize_row_selection",
                    "coalesce_duplicate_event_keys",
                    "summarize_duplicate_groups",
                    "disambiguate_duplicate_timestamps",
                    "derive_time_gap_evidence",
                    "mark_app_policy_matches",
                ],
            );
            assert_eq!(decoded.rows.len(), 5);
            REVIEW_BASE_DECODE_CACHE.with(|cache| cache.borrow_mut().take());
            REVIEW_BASE_DECODE_COUNT.with(|count| count.set(0));
            let first_cached = decode_review_base_cached(&review_base).unwrap();
            let second_cached = decode_review_base_cached(&review_base).unwrap();
            assert!(Arc::ptr_eq(&first_cached, &second_cached));
            REVIEW_BASE_DECODE_COUNT.with(|count| assert_eq!(count.get(), 1));

            let mut changed = baseline.clone();
            changed.model_concurrent_usage = true;

            let mut cached_engine = TrackedEngine::default();
            let cached = cached_engine
                .execute_with_review_base(&csv(), &review_base, &changed, support, false)
                .unwrap();
            assert!(
                cached
                    .internal_executed_queries
                    .iter()
                    .any(|query| query == "restore_review_base"),
                "review base was not restored: {:?}",
                cached.internal_executed_queries
            );
            for early_step in decoded.metadata.query_checkpoints.keys() {
                assert!(
                    !cached.executed_queries.contains(early_step),
                    "cached review reran early step {early_step}: {:?}",
                    cached.executed_queries
                );
            }

            let mut cold_engine = TrackedEngine::default();
            let cold = cold_engine
                .execute(&csv(), &changed, support, false)
                .unwrap();
            assert_result_parity(&cached.result, &cold.result, changed.usage_session_mode);

            let truncated = &review_base[..review_base.len() / 2];
            let mut corrupt_engine = TrackedEngine::default();
            let error = match corrupt_engine.execute_with_review_base(
                &csv(),
                truncated,
                &changed,
                support,
                false,
            ) {
                Ok(_) => panic!("truncated review base was accepted"),
                Err(error) => error,
            };
            assert!(
                error.contains("decompress review base")
                    || error.contains("decode review base")
                    || error.contains("payload digest mismatch"),
                "unexpected corrupt review-base error: {error}"
            );
            let mut oversized = review_base.clone();
            oversized[REVIEW_BASE_MAGIC.len()..REVIEW_BASE_MAGIC.len() + 4]
                .copy_from_slice(&((MAX_REVIEW_BASE_UNCOMPRESSED_BYTES + 1) as u32).to_le_bytes());
            let mut oversized_engine = TrackedEngine::default();
            let error = match oversized_engine.execute_with_review_base(
                &csv(),
                &oversized,
                &changed,
                support,
                false,
            ) {
                Ok(_) => panic!("oversized review base was accepted"),
                Err(error) => error,
            };
            assert!(error.contains("review base declares"), "{error}");

            let mut changed_upstream = changed.clone();
            changed_upstream.deduplicate_exact_rows = !baseline.deduplicate_exact_rows;
            let mut miss_engine = TrackedEngine::default();
            let miss = miss_engine
                .execute_with_review_base(&csv(), &review_base, &changed_upstream, support, false)
                .unwrap();
            assert!(
                miss.executed_queries
                    .iter()
                    .any(|step| step == "decode_source_records"),
                "upstream key change did not fall back to raw execution: {:?}",
                miss.executed_queries
            );
            assert!(
                !miss
                    .internal_executed_queries
                    .iter()
                    .any(|query| query == "restore_review_base"),
                "mismatched review base was restored"
            );

            for (label, changed_stops) in [
                ("same-app", {
                    let mut options = baseline.clone();
                    options.same_app_stop_types.push("CUSTOM_SAME_STOP".into());
                    options
                }),
                ("other-app", {
                    let mut options = baseline.clone();
                    options.other_stop_types.push("CUSTOM_OTHER_STOP".into());
                    options
                }),
            ] {
                let mut changed_engine = TrackedEngine::default();
                let changed_result = changed_engine
                    .execute_with_review_base(&csv(), &review_base, &changed_stops, support, false)
                    .unwrap();
                assert!(
                    !changed_result
                        .internal_executed_queries
                        .iter()
                        .any(|query| query == "restore_review_base"),
                    "{label} stop-type change restored a stale review base"
                );
                assert!(
                    changed_result
                        .executed_queries
                        .iter()
                        .any(|step| step == "disambiguate_duplicate_timestamps"),
                    "{label} stop-type change did not rebuild its early dependency cone: {:?}",
                    changed_result.executed_queries
                );
                let mut cold_engine = TrackedEngine::default();
                let cold_result = cold_engine
                    .execute(&csv(), &changed_stops, support, false)
                    .unwrap();
                assert_result_parity(
                    &changed_result.result,
                    &cold_result.result,
                    changed_stops.usage_session_mode,
                );
            }
        }

        #[test]
        fn disabled_app_mode_does_not_precompute_hidden_matcher_work() {
            let mut disabled = pipeline_options();
            disabled.usage_session_mode = UsageSessionMode::NoUsage;
            let support = PipelineV2SupportFiles::default();
            let mut producer = TrackedEngine::default();
            producer.execute(&csv(), &disabled, support, false).unwrap();
            let review_base = producer.export_review_base().unwrap().expect("base within its ceiling");
            let decoded = decode_review_base_bytes(&review_base).unwrap();
            assert!(decoded.matcher_search_suffix_digests.is_none());

            let mut enabled = disabled;
            enabled.usage_session_mode = UsageSessionMode::AppUsage;
            let mut consumer = TrackedEngine::default();
            let actual = consumer
                .execute_with_review_base(&csv(), &review_base, &enabled, support, false)
                .unwrap();
            assert!(
                actual
                    .executed_queries
                    .iter()
                    .any(|step| step == "mask_excluded_app_events"),
                "newly enabled app work was hidden behind a speculative cache: {:?}",
                actual.executed_queries
            );
            let mut cold = TrackedEngine::default();
            let expected = cold.execute(&csv(), &enabled, support, false).unwrap();
            assert_result_parity(&actual.result, &expected.result, enabled.usage_session_mode);
        }

        /// A branch-activating raw fixture for each reconstruction strategy.
        /// The explicit wider B02 arm has to close its type-19 opener through
        /// the strategy's OWN unchanged pairing rule, not merely select it:
        ///
        /// - fused, Parry--Toth, and Morrison close on another app's type 1;
        /// - foreground/background and Draxler close on same-package type 2;
        /// - GESIS sees type 20 immediately after type 19; Chronicle's partial
        ///   GESIS classifier does NOT include type 20 in its stop pool, so the
        ///   unchanged next-global-event fallback closes at that row;
        /// - EYES has a valid native pair so its two executable cells run, then
        ///   refuses the wider crossing before reconstruction.
        fn b02_strategy_fixture(strategy: EpisodeReconstructionStrategy) -> Vec<u8> {
            const HEADER: &str =
                "study_id,participant_id,username,application_label,interaction_type,app_package_name,event_timestamp,timezone\n";
            let rows = match strategy {
                EpisodeReconstructionStrategy::FusedMatcher
                | EpisodeReconstructionStrategy::ParryTothForwardPairing
                | EpisodeReconstructionStrategy::MorrisonLockTolerant => concat!(
                    "Study,P01,Target Child,Service,Foreground Service Start,com.example.service,2026-03-07 10:00:00,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Resumed,com.example.chat,2026-03-07 10:00:10,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Paused,com.example.chat,2026-03-07 10:00:20,America/Chicago\n",
                ),
                EpisodeReconstructionStrategy::ForegroundBackgroundPairing
                | EpisodeReconstructionStrategy::DraxlerInterruptionAware => concat!(
                    "Study,P01,Target Child,Service,Foreground Service Start,com.example.service,2026-03-07 10:00:00,America/Chicago\n",
                    "Study,P01,Target Child,Service,Activity Paused,com.example.service,2026-03-07 10:00:10,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Resumed,com.example.chat,2026-03-07 10:00:20,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Paused,com.example.chat,2026-03-07 10:00:30,America/Chicago\n",
                ),
                EpisodeReconstructionStrategy::GesisStartStopRepair => concat!(
                    "Study,P01,Target Child,Service,Foreground Service Start,com.example.service,2026-03-07 10:00:00,America/Chicago\n",
                    "Study,P01,Target Child,Service,Foreground Service Stop,com.example.service,2026-03-07 10:00:10,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Resumed,com.example.chat,2026-03-07 10:00:20,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Paused,com.example.chat,2026-03-07 10:00:30,America/Chicago\n",
                ),
                EpisodeReconstructionStrategy::EyesComplement => concat!(
                    "Study,P01,Target Child,Chat,Activity Resumed,com.example.chat,2026-03-07 10:00:00,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Paused,com.example.chat,2026-03-07 10:00:10,America/Chicago\n",
                ),
                EpisodeReconstructionStrategy::Schoedel2026AppWithinScreenProseV1 => concat!(
                    "Study,P01,Target Child,,Screen Interactive,android,2026-03-07 10:00:00,America/Chicago\n",
                    "Study,P01,Target Child,Service,Foreground Service Start,com.example.service,2026-03-07 10:00:01,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Resumed,com.example.chat,2026-03-07 10:00:02,America/Chicago\n",
                    "Study,P01,Target Child,Chat,Activity Paused,com.example.chat,2026-03-07 10:00:09,America/Chicago\n",
                    "Study,P01,Target Child,,Screen Non-Interactive,android,2026-03-07 10:00:10,America/Chicago\n",
                ),
            };
            format!("{HEADER}{rows}").into_bytes()
        }

        fn b02_matrix_options(
            strategy: EpisodeReconstructionStrategy,
            opener_set: OpenerSet,
        ) -> PipelineV2Options {
            let mut options = pipeline_options();
            options.usage_session_mode = UsageSessionMode::AppUsage;
            options.include_app_output = true;
            options.include_screen_output = false;
            options.correct_duplicate_event_timestamps = false;
            options.episode_reconstruction_strategy = strategy;
            options.opener_set = opener_set;
            options
        }

        fn b02_json_options(
            strategy: EpisodeReconstructionStrategy,
            opener_set: Option<&str>,
        ) -> PipelineV2Options {
            let mut request = serde_json::json!({
                "study_name": "B02 default compatibility",
                "timezone": "America/Chicago",
                "usage_session_mode": "app_usage",
                "include_app_output": true,
                "include_screen_output": false,
                "use_filter_file": false,
                "use_apps_forcing_screen_open": false,
                "use_app_codebook": false,
                "correct_duplicate_event_timestamps": false,
                "allow_stop_event_reuse": false,
                "use_activity_stopped_as_fallback": true,
                "apply_threshold_to_fallback": true,
                "long_duration_threshold_ns": 43_200_000_000_000_i64,
                "custom_app_engagement_duration": 300.0,
                "long_data_time_gap_thresholds": [1.0],
                "long_usage_duration_thresholds": [1.0],
                "same_app_stop_types": ["Activity Paused", "Activity Resumed"],
                "other_stop_types": ["Activity Resumed", "Device Shutdown"],
                "interaction_types_to_remove": [],
                "screen_auto_lock_timeout_seconds": 120.0,
                "screen_auto_lock_tolerance_seconds": 30.0,
                "screen_manual_lock_max_tail_seconds": 30.0,
                "screen_keyguard_near_stop_seconds": 2.0,
                "datetime_of_preprocessing": "2026-07-23 00:00:00 UTC",
                "materialize_visualization_data": true,
                "enable_aggregates": true,
                "episode_reconstruction_strategy": strategy.canonical_id(),
                // This detached oracle isolates the older B02 opener axis.
                // Explicitly disable the pre-existing duration floor so the
                // fixture does not acquire B04 filtering when absent direct-
                // JSON requests correctly take the published 60 s default.
                "minimum_usage_duration": 0.0,
            });
            if let Some(opener_set) = opener_set {
                request["opener_set"] = opener_set.into();
            }
            serde_json::from_value::<PipelineV2OptionsJson>(request)
                .expect("the focused B02 request parses")
                .into_pipeline_options()
        }

        fn assert_scientific_output_bytes_equal(
            actual: &PipelineV2Result,
            expected: &PipelineV2Result,
            label: &str,
        ) {
            assert_eq!(
                actual.app_csv_bytes, expected.app_csv_bytes,
                "{label}: app CSV"
            );
            assert_eq!(
                actual.screen_csv_bytes, expected.screen_csv_bytes,
                "{label}: screen CSV"
            );
            assert_eq!(
                actual.day_coverage_csv_bytes, expected.day_coverage_csv_bytes,
                "{label}: day-coverage CSV"
            );
            assert_eq!(
                actual.compliance_csv_bytes, expected.compliance_csv_bytes,
                "{label}: compliance CSV"
            );
            assert_eq!(
                actual.credited_app_csv_bytes, expected.credited_app_csv_bytes,
                "{label}: credited-app CSV"
            );
            assert_eq!(
                actual.review_summary_json_bytes, expected.review_summary_json_bytes,
                "{label}: review-summary JSON"
            );
            assert_eq!(
                actual.visualization_data_json_bytes, expected.visualization_data_json_bytes,
                "{label}: visualization JSON"
            );
            let aggregates = |result: &PipelineV2Result| {
                result
                    .aggregate_csv_outputs
                    .iter()
                    .map(|output| (output.kind.clone(), output.row_count, output.bytes.clone()))
                    .collect::<Vec<_>>()
            };
            assert_eq!(
                aggregates(actual),
                aggregates(expected),
                "{label}: aggregate CSV outputs"
            );
            assert_eq!(actual.row_lineage, expected.row_lineage, "{label}: lineage");
            assert_eq!(
                actual.app_row_count, expected.app_row_count,
                "{label}: app rows"
            );
            assert_eq!(
                actual.screen_row_count, expected.screen_row_count,
                "{label}: screen rows"
            );
        }

